/*
 * GzzhDoff HUB — patch de interface para HaxBall via InjecThor
 * By @ogzh_011
 *
 * Reconstrução nova baseada nas capturas parciais fornecidas. Não é código oficial
 * do HaxBall e não depende da API Headless. O joystick envia eventos de teclado
 * DOM para o documento da partida (iframe same-origin quando encontrado).
 * Em clientes que rejeitem eventos sintéticos, os controles visuais não poderão
 * comandar o jogo: valide no seu InjecThor antes de usar em partidas.
 */
(() => {
  'use strict';

  const VERSION = '1.0.0';
  const STORE_KEY = 'gzzhdoffHub.settings.v1';
  const INSTANCE_KEY = '__GZZHDOFF_HUB_V1__';
  const LOADING_MS = 10000;
  const MASCOT_LOLI = 'data:image/webp;base64,';
  const MASCOT_CARAMELO = 'data:image/webp;base64,';

  try {
    if (window[INSTANCE_KEY]?.destroy) window[INSTANCE_KEY].destroy();
  } catch (_) {}

  const defaults = {
    joystick: true,
    kick: true,
    mascots: true,
    fps: true,
    compact: false,
    size: 100,
    opacity: 88,
    accent: '#a855f7',
    kickKey: 'x',
    upKey: 'ArrowUp',
    downKey: 'ArrowDown',
    leftKey: 'ArrowLeft',
    rightKey: 'ArrowRight',
    floatX: null,
    floatY: null
  };

  const safeStorage = {
    get() {
      try { return JSON.parse(localStorage.getItem(STORE_KEY) || 'null') || {}; }
      catch (_) { return {}; }
    },
    set(value) {
      try { localStorage.setItem(STORE_KEY, JSON.stringify(value)); }
      catch (_) { /* armazenamento pode estar bloqueado no webview */ }
    }
  };
  const settings = { ...defaults, ...safeStorage.get() };

  const cleanKey = (key, fallback) => {
    if (typeof key !== 'string' || !key || key.length > 24) return fallback;
    return key;
  };
  settings.kickKey = cleanKey(settings.kickKey, defaults.kickKey);
  settings.upKey = cleanKey(settings.upKey, defaults.upKey);
  settings.downKey = cleanKey(settings.downKey, defaults.downKey);
  settings.leftKey = cleanKey(settings.leftKey, defaults.leftKey);
  settings.rightKey = cleanKey(settings.rightKey, defaults.rightKey);
  settings.size = Math.max(70, Math.min(150, Number(settings.size) || 100));
  settings.opacity = Math.max(25, Math.min(100, Number(settings.opacity) || 88));
  if (!/^#[0-9a-f]{6}$/i.test(settings.accent)) settings.accent = defaults.accent;

  const host = document.createElement('div');
  host.id = 'gzzhdoff-hub-root';
  host.style.cssText = 'all:initial;position:fixed;inset:0;z-index:2147483000;pointer-events:none;';
  (document.body || document.documentElement).appendChild(host);
  const shadow = host.attachShadow ? host.attachShadow({ mode: 'open' }) : host;

  const style = document.createElement('style');
  style.textContent = `
    :host{all:initial} *{box-sizing:border-box}
    .hub{--accent:${settings.accent};--scale:${settings.size / 100};--alpha:${settings.opacity / 100};font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;color:#f7f2ff;pointer-events:none;line-height:1.35;-webkit-tap-highlight-color:transparent}
    [hidden]{display:none!important}
    .hub button,.hub input{font:inherit}.hub button{color:inherit}
    .floating{position:fixed;left:calc(16px + env(safe-area-inset-left,0px));bottom:calc(24px + env(safe-area-inset-bottom,0px));width:58px;height:58px;border:1px solid #d9b4ff66;border-radius:20px;background:radial-gradient(circle at 30% 25%,#7e22ce,#170d27 70%);box-shadow:0 0 12px #a855f799,0 0 30px #7e22ce55,inset 0 0 15px #ffffff14;display:grid;place-items:center;pointer-events:auto;touch-action:none;cursor:grab;user-select:none;transition:transform .2s,box-shadow .2s;z-index:20}
    .floating:active{cursor:grabbing;transform:scale(.96)}.floating svg{width:28px;height:28px;filter:drop-shadow(0 0 5px #e9d5ff)}
    .panel{position:fixed;left:12px;bottom:calc(92px + env(safe-area-inset-bottom,0px));width:min(340px,calc(100vw - 24px));max-height:min(76vh,680px);overflow:auto;pointer-events:auto;border:1px solid #c084fc55;border-radius:22px;background:linear-gradient(145deg,#171021f5,#09070ef5 68%);backdrop-filter:blur(16px);box-shadow:0 18px 55px #000b,0 0 28px #9333ea30;opacity:0;visibility:hidden;transform:translateY(14px) scale(.96);transform-origin:bottom left;transition:opacity .22s ease,transform .26s cubic-bezier(.2,.8,.2,1),visibility .22s;overscroll-behavior:contain}
    .panel.open{opacity:1;visibility:visible;transform:translateY(0) scale(1)}.panel.compact .head{padding:10px 13px 8px}.panel.compact .section{padding:7px 12px}.panel.compact .section-title{margin-bottom:5px}.panel.compact .section-body{gap:5px}.panel.compact .status{display:none}.panel::-webkit-scrollbar{width:5px}.panel::-webkit-scrollbar-thumb{background:#a855f766;border-radius:9px}
    .head{position:sticky;top:0;z-index:2;padding:15px 16px 12px;background:linear-gradient(145deg,#221331f7,#100b18f7);border-bottom:1px solid #ffffff13;border-radius:22px 22px 0 0;display:flex;align-items:center;justify-content:space-between;gap:10px}
    .brand{display:flex;align-items:center;gap:10px}.mark{width:34px;height:34px;border-radius:12px;display:grid;place-items:center;background:linear-gradient(140deg,#a855f7,#6d28d9);box-shadow:0 0 18px #a855f755;font-weight:900;font-size:17px}.title{font-size:15px;font-weight:800;letter-spacing:.2px}.by{font-size:10px;color:#c4b5dccc;margin-top:1px}.close{border:1px solid #ffffff1c;background:#ffffff0a;border-radius:10px;width:34px;height:34px;cursor:pointer;font-size:19px}
    .section{padding:12px 14px;border-bottom:1px solid #ffffff0d}.section-title{font-size:10px;letter-spacing:1.2px;text-transform:uppercase;color:#c4b5fd;font-weight:800;margin-bottom:9px}.section-body{display:grid;gap:8px}
    .toggle-row{display:flex;align-items:center;justify-content:space-between;gap:12px;min-height:32px;font-size:12px;color:#f4edff}.toggle{appearance:none;width:37px;height:21px;border-radius:99px;background:#383142;border:1px solid #ffffff20;position:relative;cursor:pointer;transition:.2s;flex:none}.toggle:before{content:"";position:absolute;width:15px;height:15px;left:2px;top:2px;border-radius:50%;background:#d6cce1;transition:.2s}.toggle:checked{background:var(--accent);box-shadow:0 0 12px color-mix(in srgb,var(--accent),transparent 45%)}.toggle:checked:before{transform:translateX(16px);background:#fff}
    .range-row{display:grid;grid-template-columns:1fr auto;align-items:center;gap:5px 10px;font-size:11px}.range-row input[type=range]{grid-column:1/-1;width:100%;accent-color:var(--accent);height:20px}.value{color:#d8b4fe;font-variant-numeric:tabular-nums}.color-row{display:flex;align-items:center;justify-content:space-between;font-size:11px}.color-row input{width:42px;height:28px;border:0;padding:0;background:none}
    .key-row{display:grid;grid-template-columns:1fr auto;align-items:center;gap:8px;font-size:11px}.key-button{min-width:74px;border:1px solid #ffffff20;border-radius:9px;background:#ffffff0b;padding:6px 9px;font-size:10px;cursor:pointer}.key-button.waiting{border-color:var(--accent);box-shadow:0 0 8px #a855f755}
    .status{font-size:10px;color:#c4b5d9;padding:0 14px 12px}.version{color:#988aa8}
    .fps{position:fixed;right:10px;top:calc(10px + env(safe-area-inset-top,0px));padding:5px 8px;border:1px solid #ffffff20;border-radius:9px;background:#0b0812d9;color:#e9d5ff;font-size:10px;pointer-events:none;box-shadow:0 0 15px #7e22ce22}
    .control{position:fixed;pointer-events:auto;touch-action:none;user-select:none;-webkit-user-select:none;transform:scale(var(--scale));transform-origin:bottom left}
    .joystick{width:132px;height:132px;left:calc(16px + env(safe-area-inset-left,0px));bottom:calc(25px + env(safe-area-inset-bottom,0px));border:1px solid #d8b4fe66;border-radius:50%;background:radial-gradient(circle,#ffffff08 0 24%,#a855f729 26% 66%,#120b1bcc 68%);box-shadow:0 0 18px #a855f733,inset 0 0 18px #a855f722;display:grid;place-items:center;opacity:var(--alpha)}
    .stick{width:48px;height:48px;border:1px solid #e9d5ff88;border-radius:50%;background:radial-gradient(circle at 35% 30%,#c084fc,#6b21a8 78%);box-shadow:0 0 15px #a855f799;position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);transition:transform .04s linear}
    .kick{right:calc(24px + env(safe-area-inset-right,0px));bottom:calc(45px + env(safe-area-inset-bottom,0px));width:75px;height:75px;border-radius:50%;border:1px solid #f0abfcaa;background:radial-gradient(circle at 35% 25%,#c026d3,#4c1d68 72%);box-shadow:0 0 20px #d946ef66,inset 0 0 12px #ffffff20;display:grid;place-items:center;opacity:var(--alpha);font-size:12px;font-weight:900;letter-spacing:.8px;text-shadow:0 1px 6px #000;transition:transform .08s,filter .15s}.kick.active{transform:scale(calc(var(--scale)*.9));filter:brightness(1.3)}
    .mascots{position:fixed;right:10px;bottom:calc(128px + env(safe-area-inset-bottom,0px));display:flex;align-items:flex-end;gap:2px;pointer-events:none;opacity:var(--alpha);filter:drop-shadow(0 5px 12px #0008)}.mascots img{width:clamp(52px,17vw,95px);max-height:25vh;object-fit:contain;animation:float 3.5s ease-in-out infinite}.mascots img+img{animation-delay:.6s;width:clamp(46px,15vw,82px)}
    @keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}
    .loader{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;pointer-events:auto;background:radial-gradient(ellipse at 50% 45%,#35134b 0,#130b1d 48%,#07060b 100%);transition:opacity .35s ease,visibility .35s;z-index:50}.loader.hide{opacity:0;visibility:hidden;pointer-events:none}.load-card{width:min(330px,calc(100vw - 44px));padding:25px 22px 20px;text-align:center;border:1px solid #d8b4fe45;border-radius:25px;background:#110a1bcc;box-shadow:0 0 45px #7e22ce2b;animation:loadIn .55s ease both}.load-mark{width:64px;height:64px;margin:0 auto 14px;border-radius:22px;display:grid;place-items:center;font-weight:950;font-size:29px;background:linear-gradient(140deg,#a855f7,#4c1d95);box-shadow:0 0 32px #a855f777;animation:pulse 1.8s ease-in-out infinite}.load-title{font-size:20px;font-weight:900;letter-spacing:.4px}.load-sub{font-size:11px;color:#c4b5d9;margin:6px 0 17px}.track{height:8px;border-radius:99px;background:#ffffff16;overflow:hidden}.progress{height:100%;width:0;border-radius:99px;background:linear-gradient(90deg,#7c3aed,#e879f9);box-shadow:0 0 14px #c084fc;transition:width .08s linear}.load-meta{display:flex;justify-content:space-between;font-size:10px;color:#c4b5d9;margin-top:8px}.skip{margin-top:16px;border:1px solid #c084fc55;border-radius:11px;background:#a855f71c;padding:8px 13px;font-size:11px;cursor:pointer}
    @keyframes loadIn{from{opacity:0;transform:translateY(12px) scale(.97)}to{opacity:1;transform:none}}@keyframes pulse{50%{box-shadow:0 0 42px #d946ef99;transform:scale(1.04)}}
    @media(max-width:380px){.panel{left:8px;width:calc(100vw - 16px);bottom:calc(82px + env(safe-area-inset-bottom,0px))}.joystick{width:118px;height:118px}.kick{width:68px;height:68px}}
    @media(min-width:700px){.joystick{width:145px;height:145px}.kick{width:82px;height:82px}}
    @media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}
  `;
  shadow.appendChild(style);

  const wrap = document.createElement('div');
  wrap.className = 'hub';
  wrap.innerHTML = `
    <button class="floating" type="button" aria-label="Abrir Config HUB" title="Arraste para mover · toque para abrir">
      <svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M12 2.8 14.6 8l5.7.8-4.1 4 .97 5.7L12 15.8l-5.1 2.7.98-5.7-4.15-4L9.45 8 12 2.8Z" stroke="white" stroke-width="1.5" stroke-linejoin="round"/><path d="M12 6.6v5.5m0 0 2.2-2.2M12 12.1l-2.2-2.2" stroke="white" stroke-width="1.25" stroke-linecap="round"/></svg>
    </button>
    <section class="panel" role="dialog" aria-label="Config HUB">
      <header class="head"><div class="brand"><div class="mark">G</div><div><div class="title">GzzhDoff HUB</div><div class="by">By @ogzh_011</div></div></div><button class="close" type="button" aria-label="Minimizar painel">×</button></header>
      <div class="section"><div class="section-title">Controles</div><div class="section-body">
        <label class="toggle-row">Joystick virtual <input class="toggle" data-setting="joystick" type="checkbox"></label>
        <label class="toggle-row">Botão de chute <input class="toggle" data-setting="kick" type="checkbox"></label>
        <label class="toggle-row">Mascotes <input class="toggle" data-setting="mascots" type="checkbox"></label>
        <label class="toggle-row">FPS do navegador <input class="toggle" data-setting="fps" type="checkbox"></label>
      </div></div>
      <div class="section"><div class="section-title">Aparência</div><div class="section-body">
        <label class="range-row"><span>Tamanho dos controles</span><span class="value" data-value="size"></span><input type="range" min="70" max="150" step="5" data-setting="size"></label>
        <label class="range-row"><span>Transparência</span><span class="value" data-value="opacity"></span><input type="range" min="25" max="100" step="5" data-setting="opacity"></label>
        <label class="color-row">Cor neon <input type="color" data-setting="accent"></label>
        <label class="toggle-row">Modo compacto <input class="toggle" data-setting="compact" type="checkbox"></label>
      </div></div>
      <div class="section"><div class="section-title">Teclas enviadas ao jogo</div><div class="section-body">
        <div class="key-row"><span>Chute</span><button class="key-button" data-key="kickKey" type="button"></button></div>
        <div class="key-row"><span>Cima</span><button class="key-button" data-key="upKey" type="button"></button></div>
        <div class="key-row"><span>Baixo</span><button class="key-button" data-key="downKey" type="button"></button></div>
        <div class="key-row"><span>Esquerda</span><button class="key-button" data-key="leftKey" type="button"></button></div>
        <div class="key-row"><span>Direita</span><button class="key-button" data-key="rightKey" type="button"></button></div>
      </div></div>
      <div class="status">O patch envia eventos de teclado ao cliente HaxBall. Se o carregador bloquear eventos sintéticos, os controles móveis podem não ser aceitos.</div>
      <div class="status version">GzzhDoff HUB v${VERSION} · FPS mede o navegador, não o motor do jogo.</div>
    </section>
    <div class="fps" hidden>— FPS · navegador</div>
    <div class="control joystick" aria-label="Joystick virtual" role="application"><div class="stick"></div></div>
    <button class="control kick" type="button" aria-label="Chutar">CHUTE</button>
    <div class="mascots" aria-hidden="true"><img alt="Loli"/><img alt="Caramelo"/></div>
    <div class="loader"><div class="load-card"><div class="load-mark">G</div><div class="load-title">GzzhDoff HUB</div><div class="load-sub">Preparando o painel e os controles</div><div class="track"><div class="progress"></div></div><div class="load-meta"><span>Inicializando</span><span class="percent">0%</span></div><button class="skip" type="button">Entrar antes</button></div></div>
  `;
  shadow.appendChild(wrap);

  const $ = (selector) => wrap.querySelector(selector);
  const $$ = (selector) => [...wrap.querySelectorAll(selector)];
  const floating = $('.floating');
  const panel = $('.panel');
  const joystick = $('.joystick');
  const stick = $('.stick');
  const kickButton = $('.kick');
  const fpsBadge = $('.fps');
  const mascots = $('.mascots');
  const loader = $('.loader');
  const progress = $('.progress');
  const percent = $('.percent');

  // Optional custom art is embedded into this single JS file at build time.
  const mascotImages = $$('.mascots img');
  if (MASCOT_LOLI.startsWith('data:image/')) mascotImages[0].src = MASCOT_LOLI;
  else mascotImages[0].remove();
  if (MASCOT_CARAMELO.startsWith('data:image/')) mascotImages[1].src = MASCOT_CARAMELO;
  else mascotImages[1].remove();

  function persist() { safeStorage.set(settings); }
  function syncUI() {
    wrap.style.setProperty('--accent', settings.accent);
    wrap.style.setProperty('--scale', String(settings.size / 100));
    wrap.style.setProperty('--alpha', String(settings.opacity / 100));
    joystick.hidden = !settings.joystick;
    kickButton.hidden = !settings.kick;
    mascots.hidden = !settings.mascots || mascotImages.every((img) => !img.isConnected);
    fpsBadge.hidden = !settings.fps;
    panel.classList.toggle('compact', !!settings.compact);
    $$('[data-setting]').forEach((input) => {
      const key = input.dataset.setting;
      if (input.type === 'checkbox') input.checked = !!settings[key];
      else input.value = settings[key];
    });
    $$('[data-value]').forEach((node) => { node.textContent = `${settings[node.dataset.value]}%`; });
    $('[data-key="kickKey"]').textContent = displayKey(settings.kickKey);
    ['upKey','downKey','leftKey','rightKey'].forEach((key) => { $(`[data-key="${key}"]`).textContent = displayKey(settings[key]); });
    if (Number.isFinite(settings.floatX) && Number.isFinite(settings.floatY)) {
      floating.style.left = `${settings.floatX}px`;
      floating.style.top = `${settings.floatY}px`;
      floating.style.bottom = 'auto';
    }
  }
  function displayKey(key) {
    if (key.startsWith('Arrow')) return key.replace('Arrow', '');
    if (key === ' ') return 'Space';
    return key.length === 1 ? key.toUpperCase() : key;
  }

  // Locate the same-origin game frame used by the page around HaxBall.
  function gameContext() {
    try {
      const frame = document.querySelector('.gameframe');
      if (frame?.contentWindow?.document) {
        return { win: frame.contentWindow, doc: frame.contentWindow.document };
      }
    } catch (_) { /* cross-origin frame: browser blocks direct keyboard injection */ }
    try {
      if (document.querySelector('canvas') || document.querySelector('#game')) return { win: window, doc: document };
    } catch (_) {}
    try {
      const parent = window.parent;
      if (parent && parent !== window) {
        const frame = [...parent.document.querySelectorAll('iframe')].find((el) => el.contentWindow === window);
        if (frame) return { win: window, doc: document };
      }
    } catch (_) {}
    return { win: window, doc: document };
  }

  const keyCodes = { ArrowUp: 38, ArrowDown: 40, ArrowLeft: 37, ArrowRight: 39, ' ': 32 };
  function keyInfo(key) {
    if (keyCodes[key]) return { key, code: key === ' ' ? 'Space' : key, keyCode: keyCodes[key], which: keyCodes[key] };
    const upper = key.toUpperCase();
    const code = /^[A-Z]$/.test(upper) ? `Key${upper}` : key;
    const codeNum = /^[A-Z]$/.test(upper) ? upper.charCodeAt(0) : 0;
    return { key, code, keyCode: codeNum, which: codeNum };
  }
  const activeKeys = new Map();
  function sendKey(key, down) {
    key = cleanKey(key, 'x');
    const id = key.toLowerCase();
    if (down && activeKeys.has(id)) return;
    if (!down && !activeKeys.has(id)) return;
    const { win, doc } = gameContext();
    const info = keyInfo(key);
    const event = new KeyboardEvent(down ? 'keydown' : 'keyup', {
      key: info.key, code: info.code, keyCode: info.keyCode, which: info.which,
      bubbles: true, cancelable: true, composed: true, repeat: false
    });
    const target = doc.body || doc.documentElement || doc;
    try { target.dispatchEvent(event); } catch (_) { try { doc.dispatchEvent(event); } catch (_) {} }
    if (down) activeKeys.set(id, key); else activeKeys.delete(id);
    // Only a diagnostic event for extensions/debugging; HaxBall receives the DOM keyboard event above.
    try { win.dispatchEvent(new CustomEvent('gzzhdoff:input', { detail: { key, down } })); } catch (_) {}
  }
  function releaseAll() { [...activeKeys.values()].forEach((key) => sendKey(key, false)); }

  function togglePanel(force) {
    const shouldOpen = typeof force === 'boolean' ? force : !panel.classList.contains('open');
    panel.classList.toggle('open', shouldOpen);
    floating.setAttribute('aria-label', shouldOpen ? 'Minimizar Config HUB' : 'Abrir Config HUB');
  }
  floating.addEventListener('click', () => togglePanel());
  $('.close').addEventListener('click', () => togglePanel(false));

  // Drag the floating HUB button on touch or mouse without accidentally opening it.
  let drag = null;
  floating.addEventListener('pointerdown', (event) => {
    drag = { id: event.pointerId, x: event.clientX, y: event.clientY, left: floating.getBoundingClientRect().left, top: floating.getBoundingClientRect().top, moved: false };
    try { floating.setPointerCapture(event.pointerId); } catch (_) {}
  });
  floating.addEventListener('pointermove', (event) => {
    if (!drag || drag.id !== event.pointerId) return;
    const dx = event.clientX - drag.x, dy = event.clientY - drag.y;
    if (Math.abs(dx) + Math.abs(dy) > 6) drag.moved = true;
    if (drag.moved) {
      const x = Math.max(4, Math.min(innerWidth - floating.offsetWidth - 4, drag.left + dx));
      const y = Math.max(4, Math.min(innerHeight - floating.offsetHeight - 4, drag.top + dy));
      floating.style.left = `${x}px`; floating.style.top = `${y}px`; floating.style.bottom = 'auto';
    }
  });
  const endDrag = () => {
    if (drag?.moved) {
      settings.floatX = parseFloat(floating.style.left); settings.floatY = parseFloat(floating.style.top); persist();
      // Suppress the synthetic click generated at the end of a drag.
      floating.dataset.dragged = '1'; setTimeout(() => delete floating.dataset.dragged, 0);
    }
    drag = null;
  };
  floating.addEventListener('pointerup', endDrag); floating.addEventListener('pointercancel', endDrag);
  floating.addEventListener('click', (event) => { if (floating.dataset.dragged === '1') { event.stopImmediatePropagation(); delete floating.dataset.dragged; } }, true);

  $$('[data-setting]').forEach((input) => {
    const update = () => {
      const key = input.dataset.setting;
      settings[key] = input.type === 'checkbox' ? input.checked : input.type === 'range' ? Number(input.value) : input.value;
      persist(); syncUI();
    };
    input.addEventListener('input', update); input.addEventListener('change', update);
  });

  // Key capture lets users match the controls they already configured in HaxBall.
  let waitingFor = null;
  $$('[data-key]').forEach((button) => button.addEventListener('click', () => {
    waitingFor = button.dataset.key;
    button.classList.add('waiting'); button.textContent = 'Pressione tecla…';
  }));
  function onKeyCapture(event) {
    if (!waitingFor) return;
    event.preventDefault(); event.stopPropagation();
    const value = event.key === ' ' ? ' ' : event.key;
    if (value === 'Escape') { waitingFor = null; syncUI(); return; }
    settings[waitingFor] = value;
    waitingFor = null; persist(); syncUI();
  }
  window.addEventListener('keydown', onKeyCapture, true);

  // Touch joystick: converts the stick direction to configured press/release events.
  const dirToKey = { up: () => settings.upKey, down: () => settings.downKey, left: () => settings.leftKey, right: () => settings.rightKey };
  let pointerId = null;
  let currentDirections = new Set();
  function setDirections(next) {
    next.forEach((direction) => { if (!currentDirections.has(direction)) sendKey(dirToKey[direction](), true); });
    currentDirections.forEach((direction) => { if (!next.has(direction)) sendKey(dirToKey[direction](), false); });
    currentDirections = next;
  }
  function moveStick(clientX, clientY) {
    const box = joystick.getBoundingClientRect();
    const cx = box.left + box.width / 2, cy = box.top + box.height / 2;
    const dx = clientX - cx, dy = clientY - cy;
    const radius = box.width * .32;
    const length = Math.hypot(dx, dy) || 1;
    const px = dx / length * Math.min(length, radius), py = dy / length * Math.min(length, radius);
    stick.style.transform = `translate(calc(-50% + ${px}px),calc(-50% + ${py}px))`;
    const dead = box.width * .13;
    const next = new Set();
    if (Math.abs(dx) > dead) next.add(dx < 0 ? 'left' : 'right');
    if (Math.abs(dy) > dead) next.add(dy < 0 ? 'up' : 'down');
    setDirections(next);
  }
  function resetStick() { pointerId = null; setDirections(new Set()); stick.style.transform = 'translate(-50%,-50%)'; }
  joystick.addEventListener('pointerdown', (event) => { event.preventDefault(); pointerId = event.pointerId; try { joystick.setPointerCapture(pointerId); } catch (_) {} moveStick(event.clientX, event.clientY); });
  joystick.addEventListener('pointermove', (event) => { if (pointerId === event.pointerId) { event.preventDefault(); moveStick(event.clientX, event.clientY); } });
  joystick.addEventListener('pointerup', (event) => { if (pointerId === event.pointerId) resetStick(); });
  joystick.addEventListener('pointercancel', resetStick);

  function startKick(event) { event.preventDefault(); sendKey(settings.kickKey, true); kickButton.classList.add('active'); }
  function endKick() { sendKey(settings.kickKey, false); kickButton.classList.remove('active'); }
  kickButton.addEventListener('pointerdown', startKick);
  kickButton.addEventListener('pointerup', endKick);
  kickButton.addEventListener('pointercancel', endKick);
  kickButton.addEventListener('lostpointercapture', endKick);
  kickButton.addEventListener('contextmenu', (event) => event.preventDefault());
  window.addEventListener('blur', releaseAll);
  document.addEventListener('visibilitychange', () => { if (document.hidden) releaseAll(); });

  // Browser animation-frame estimate (not the internal game simulation FPS).
  let raf = 0, frameCount = 0, fpsStart = performance.now();
  function countFrame(now) {
    frameCount++;
    if (now - fpsStart >= 1000) {
      fpsBadge.textContent = `${Math.round(frameCount * 1000 / (now - fpsStart))} FPS · navegador`;
      frameCount = 0; fpsStart = now;
    }
    raf = requestAnimationFrame(countFrame);
  }
  raf = requestAnimationFrame(countFrame);

  // Requested 10-second animated splash, with a user-facing skip control.
  let loaderStart = performance.now();
  let loaderRaf = 0;
  let loaderDone = false;
  function finishLoader() {
    if (loaderDone) return;
    loaderDone = true; cancelAnimationFrame(loaderRaf); loader.classList.add('hide');
  }
  function animateLoader(now) {
    const pct = Math.min(100, ((now - loaderStart) / LOADING_MS) * 100);
    progress.style.width = `${pct}%`; percent.textContent = `${Math.floor(pct)}%`;
    if (pct >= 100) finishLoader(); else loaderRaf = requestAnimationFrame(animateLoader);
  }
  $('.skip').addEventListener('click', finishLoader);
  loaderRaf = requestAnimationFrame(animateLoader);

  syncUI();

  const api = {
    version: VERSION,
    open: () => togglePanel(true),
    close: () => togglePanel(false),
    destroy() {
      releaseAll(); cancelAnimationFrame(raf); cancelAnimationFrame(loaderRaf);
      window.removeEventListener('keydown', onKeyCapture, true);
      host.remove();
      try { delete window[INSTANCE_KEY]; } catch (_) {}
    }
  };
  try { Object.defineProperty(window, INSTANCE_KEY, { value: api, configurable: true }); }
  catch (_) { window[INSTANCE_KEY] = api; }
})();
